{
  "name": "oliver-tree-ai-marketplace",
  "owner": {
    "name": "Michael Oliver",
    "url": "https://github.com/moliver28"
  },
  "plugins": [
    {
      "name": "humanizer-voice",
      "source": "./plugins/humanizer",
      "description": "Learned voice profile + quiet delivery gate; user surface is /voice. Learn once, scan in background, patch-in-place repairs.",
      "version": "0.2.0",
      "category": "writing"
    },
    {
      "name": "voice-gate",
      "source": "./plugins/voice-gate",
      "description": "Deterministic pre-delivery tell gate: 55-pattern regex scan (plus optional embedder cosine), fail-open, span-level repair contracts. Reference implementation behind the /voice gate.",
      "version": "0.1.0",
      "category": "writing"
    },
    {
      "name": "decision-advisor",
      "source": "./plugins/decision-advisor",
      "description": "Meta-cognitive decision analysis for one-way doors: expand options, contract to the elegant solution, embed enforcement. Use when the user says: 'decide whether to...', 'run a meta-decision on...', 'stress-test this decision'.",
      "version": "0.1.0",
      "category": "engineering"
    }
  ]
}
